// elvish: backend + emitter (elvish 0.21+: os:exists, str, math, platform modules).
#include "shell.hpp"
#include "emit_dialect.hpp"
namespace {
using namespace forge::script;
std::string eq(const std::string& s) { return shellq::doubled(s, '\''); }
struct elvish_dialect : block_dialect {
    std::string header() override {
        return "#!/usr/bin/env elvish\n# generated by `forge script --emit elvish`; runs without FORGE\nuse str\nuse math\nuse os\nuse platform\nvar _r = ''\n"
               "fn _platform { var o = $platform:os; if (eq $o darwin) { put macos } elif (has-value [linux windows freebsd android] $o) { put $o } else { put other } }\n";
    }
    std::string s_lit(const std::string& s) override { return eq(s); }
    std::string ref(const std::string& n, ety, bool) override { return "$" + n; }
    std::string arith(char op, const std::string& a, const std::string& b) override {
        if (op == '/') return "(math:trunc (/ " + a + " " + b + "))";
        return "(" + std::string(1, op) + " " + a + " " + b + ")";
    }
    std::string neg(const std::string& a) override { return "(- 0 " + a + ")"; }
    std::string concat(const std::vector<std::string>& p) override { std::string o; for (auto& x : p) o += x; return o; }
    std::string i2s(const std::string& i) override { return "(to-string " + i + ")"; }
    std::string s2i(const std::string& s) override { return "(num " + s + ")"; }
    std::string slen(const std::string& s) override { return "(count " + s + ")"; }
    std::string cmp(const std::string& op, const std::string& a, const std::string& b, bool ints) override {
        std::string o = op; if (!ints) o += "s";
        return "(" + o + " " + a + " " + b + ")";
    }
    std::string c_and(const std::string& a, const std::string& b) override { return "(and " + a + " " + b + ")"; }
    std::string c_or(const std::string& a, const std::string& b) override { return "(or " + a + " " + b + ")"; }
    std::string c_not(const std::string& a) override { return "(not " + a + ")"; }
    std::string c_bool(bool v) override { return v ? "$true" : "$false"; }
    std::string truthy(const std::string& v) override { return "(==s " + v + " 'true')"; }
    void let(const std::string& n, const std::string& v, ety, bool, bool decl) override { L((decl ? "var " : "set ") + n + " = " + v); }
    void print(const std::string& v, bool nl, bool err) override { L((nl ? "echo " : "print ") + v + (err ? " >&2" : "")); }
    void if_(const std::string& c) override { open("if " + c + " {"); }
    void else_() override { mid("} else {"); }
    void end_if() override { close("}"); }
    void while_(const std::string& c) override { open("while " + c + " {"); }
    void end_while() override { close("}"); }
    void for_(const std::string& v, const std::vector<std::string>& items) override { std::string s; for (auto& i : items) s += (s.empty() ? "" : " ") + i; open("for " + v + " [" + s + "] {"); }
    void end_for() override { close("}"); }
    void brk() override { L("break"); }
    void cont() override { L("continue"); }
    void fn_(const std::string& name, const std::vector<std::string>& ps) override {
        std::string s; for (auto& p : ps) s += (s.empty() ? "" : " ") + p;
        open("fn " + name + " {|" + s + "|");
    }
    void end_fn() override { close("}"); }
    void ret(const std::string& v) override { if (!v.empty()) L("set _r = " + v); L("return"); }
    std::string call(const std::string& name, const std::vector<std::string>& a, bool want, ety) override {
        std::string s = name; for (auto& x : a) s += " " + x;
        L(s);
        if (!want) return "";
        auto t = cx->tmp(); let(t, "$_r", ety::Str, false, true); return "$" + t;
    }
    void exit_(const std::string& c) override { L("exit " + c); }
    std::string env(const std::string& n, const std::string& d) override { return "(if (has-env " + n + ") { get-env " + n + " } else { put " + d + " })"; }
    void setenv(const std::string& n, const std::string& v) override { L("set-env " + n + " " + v); }
    std::string test_path(const std::string& p, char k) override {
        if (k == 'd') return "(os:is-dir " + p + ")";
        if (k == 'f') return "(os:is-regular " + p + ")";
        return "(os:exists " + p + ")";
    }
    void mkdir(const std::string& p) override { L("os:mkdir-all " + p); }
    void remove(const std::string& p) override { L("os:remove-all " + p); }
    void write(const std::string& p, const std::string& s, bool app) override { L("print " + s + (app ? " >> " : " > ") + p); }
    std::string read(const std::string& p) override { return "(slurp < " + p + ")"; }
    std::string cwd() override { return "$pwd"; }
    std::string platform() override { return "(_platform)"; }
    void run(const std::string& cmd, const std::string& o, const std::string& c, bool host) override {
        if (host) L("set " + o + " = (elvish -norc -c " + cmd + " | slurp)" + "; set " + c + " = 0");
        else {
            L("set " + o + " = (sh -c " + eq(sh_wrapper()) + " _ " + cmd + " | slurp)");
            L("var _i = (str:last-index $" + o + " \"\\x1c\")");
            L("set " + c + " = (num $" + o + "[(+ $_i 1)..])");
            L("set " + o + " = $" + o + "[..$_i]");
        }
    }
    std::string sh_quote(const std::string& v) override { return "\"'\"(str:replace \"'\" \"'\\\\''\" " + v + ")\"'\""; }
};
} // namespace
void forge_shell_register_elvish(forge::script::shell_registry& r) {
    forge::script::shell_backend b; b.name = "elvish"; b.exes = {"elvish"}; b.family = "elvish"; b.golden_tested = true;
    b.argv = [](const std::string& exe, const std::string& sc) -> std::vector<std::string> { return {exe, "-norc", "-c", sc}; };
    b.quote = eq;
    b.emitter = [] { return std::make_unique<elvish_dialect>(); }; b.emit_ext = ".elv"; b.emit_tested = true;
    r.add(std::move(b));
}
